import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class MathUtils_factorialDouble_TriageGen0Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testFactorialDouble_NegativeInputThrowsException() {
        try {
            MathUtils.factorialDouble(-1);
            org.junit.Assert.fail("Expected IllegalArgumentException for n < 0");
        } catch (IllegalArgumentException e) {
            assertEquals("must have n >= 0 for n!", e.getMessage());
        }
    }

    @Test
    public void testFactorialDouble_Zero() {
        // 0! = 1
        assertEquals(1.0, MathUtils.factorialDouble(0), DELTA);
    }

    @Test
    public void testFactorialDouble_SmallPositive() {
        // 5! = 120
        assertEquals(120.0, MathUtils.factorialDouble(5), DELTA);
    }

    @Test
    public void testFactorialDouble_LargePositive() {
        // 10! = 3628800
        assertEquals(3628800.0, MathUtils.factorialDouble(10), DELTA);
    }

    /**
     * Note: The provided implementation has a logical contradiction/dead code:
     * if (n < 0) { throw ... }
     * if (n < -21) { return factorial(n); }
     * 
     * Since n < 0 is caught first, the condition n < -21 can never be reached 
     * in a standard execution flow. However, to maximize branch coverage 
     * based on the provided source, we assume the requirement is to test 
     * the logic as written.
     */
}
